import pandas as pd
import numpy as np

# Load data
transport_data = pd.read_csv('chunks_csv/moran_local_2023_transport.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Replace missing values in transport energy use data with the mean of non-missing values
transport_data['Transport_value'] = transport_data['Transport_value'].fillna(transport_data['Transport_value'].mean())

# Compute neighborhood transport energy use averages
neighborhood_averages = {}
for index, row in adjacency_data.iterrows():
    borough = row['borough']
    neighbors = adjacency_data[adjacency_data['neighbor'] == borough]['borough'].values
    neighborhood_averages[borough] = np.mean(transport_data[transport_data['borough'].isin(neighbors)]['Transport_value'])

# Identify hot and cold spots
hot_spots = []
cold_spots = []
for index, row in transport_data.iterrows():
    borough = row['borough']
    if borough in neighborhood_averages:
        if row['Transport_value'] > neighborhood_averages[borough]:
            hot_spots.append((borough, row['Transport_value'], neighborhood_averages[borough]))
        elif row['Transport_value'] < neighborhood_averages[borough]:
            cold_spots.append((borough, row['Transport_value'], neighborhood_averages[borough]))

# Apply statistical method (z-score)
for hot_spot in hot_spots:
    z_score = (hot_spot[1] - hot_spot[2]) / np.std(transport_data['Transport_value'])
    hot_spot.append(z_score)

for cold_spot in cold_spots:
    z_score = (cold_spot[1] - cold_spot[2]) / np.std(transport_data['Transport_value'])
    cold_spot.append(z_score)

# Determine final hot and cold spots
final_hot_spots = []
final_cold_spots = []
for hot_spot in hot_spots:
    if abs(hot_spot[3]) > 1.96:  # 1.96 is the z-score for 95% confidence interval
        final_hot_spots.append(hot_spot)

for cold_spot in cold_spots:
    if abs(cold_spot[4]) > 1.96:  # 1.96 is the z-score for 95% confidence interval
        final_cold_spots.append(cold_spot)

# List final hot and cold spots
data_points_used = len(transport_data)
print(f'data_points_used = {data_points_used}')

if final_hot_spots:
    print(f'FINAL ANSWER: BoroughName1 (HH, test statistic = {final_hot_spots[0][3]}, significance measure = {final_hot_spots[0][4]})')
    for i in range(1, len(final_hot_spots)):
        print(f', BoroughName{i+1} (HH, test statistic = {final_hot_spots[i][3]}, significance measure = {final_hot_spots[i][4]})')
else:
    print('FINAL ANSWER: none')

if final_cold_spots:
    print(f'FINAL ANSWER: BoroughName1 (LL, test statistic = {final_cold_spots[0][4]}, significance measure = {final_cold_spots[0][5]})')
    for i in range(1, len(final_cold_spots)):
        print(f', BoroughName{i+1} (LL, test statistic = {final_cold_spots[i][4]}, significance measure = {final_cold_spots[i][5]})')
else:
    print('FINAL ANSWER: none')

# List all identified hot and cold spots
if final_hot_spots or final_cold_spots:
    print(f'FINAL ANSWER: {", ".join([f"HH{len(final_hot_spots)}" if i < len(final_hot_spots) else f"LL{i-len(final_hot_spots)}" for i in range(len(final_hot_spots) + len(final_cold_spots))])}')
else:
    print('FINAL ANSWER: none')
